function emptiestShelves(shelves: number[][], k: number): number[] {
  const rows = shelves.map((row, i) => [row.reduce((a, b) => a + b, 0), i]);
  rows.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  return rows.slice(0, k).map(p => p[1]);
}

