function emptiestShelves(shelves: number[][], k: number): number[] {
  // first index holding 0 = number of 1s
  const countOnes = (row: number[]): number => {
    let lo = 0, hi = row.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (row[mid] === 1) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  };
  // max-heap of [count, row]: the fullest kept row sits on top
  const heap: number[][] = [];
  const bigger = (a: number[], b: number[]) => a[0] > b[0] || (a[0] === b[0] && a[1] > b[1]);
  const push = (x: number[]) => {
    heap.push(x);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!bigger(heap[i], heap[p])) break;
      [heap[i], heap[p]] = [heap[p], heap[i]];
      i = p;
    }
  };
  const pop = (): number[] => {
    const top = heap[0], last = heap.pop()!;
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < heap.length && bigger(heap[l], heap[m])) m = l;
        if (r < heap.length && bigger(heap[r], heap[m])) m = r;
        if (m === i) break;
        [heap[i], heap[m]] = [heap[m], heap[i]];
        i = m;
      }
    }
    return top;
  };
  shelves.forEach((row, i) => {
    push([countOnes(row), i]);
    if (heap.length > k) pop();
  });
  const out: number[] = [];
  while (heap.length) out.push(pop()[1]);
  return out.reverse();
}

